    public class OpportunityWinUnitOfWork extends fflib_SObjectUnitOfWork {
        private List<Deal_Won__e> eventsToPublish = new List<Deal_Won__e>();

        public OpportunityWinUnitOfWork(List<SObjectType> objectTypes) {
            super(objectTypes);
        }

        public void registerEventsToPublish(List<Deal_Won__e> events) {
            if (events != null && !events.isEmpty()) {
                eventsToPublish.addAll(events);
            }
        }

        public override void commitWork() {
            Savepoint savepoint = Database.setSavepoint();

            try {
                // Commit the opportunity DML first. Publish Immediately events are
                // published only after this succeeds.
                super.commitWork();

                if (!eventsToPublish.isEmpty()) {
                    List<Database.SaveResult> results = EventBus.publish(eventsToPublish);
                    for (Database.SaveResult result : results) {
                        if (!result.isSuccess()) {
                            for (Database.Error error : result.getErrors()) {
                                throw new EventPublishException(error.getMessage());
                            }
                        }
                    }
                }
            } catch (Exception e) {
                Database.rollback(savepoint);
                throw e;
            }
        }
    }

    private class EventPublishException extends Exception {
    }

    public static final UnitOfWorkFactory UnitOfWork = new UnitOfWorkFactory();

    public static final fflib_Application.SelectorFactory Selector =
        new fflib_Application.SelectorFactory(
            new Map<SObjectType, Type>{ Opportunity.SObjectType => OpportunitiesSelector.class }
        );
