public with sharing class LineItemDiscountHandler {
    public static void applyStandardDiscounts(List<OpportunityLineItem> lineItems) {
        Set<Id> productIds = new Set<Id>();

        for (OpportunityLineItem line : lineItems) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> discountsByProductId = new Map<Id, Decimal>();
        for (Product2 product : [
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIds
        ]) {
            discountsByProductId.put(
                product.Id,
                PricingRules.standardDiscountForFamily(product.Family)
            );
        }

        for (OpportunityLineItem line : lineItems) {
            if (line.Discount == null && discountsByProductId.containsKey(line.Product2Id)) {
                line.Discount = discountsByProductId.get(line.Product2Id);
            }
        }
    }
}
